INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '目的对应', 'kp-xingce-judgement-analogy-corresponding-purpose', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "目的对应"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "做 A 动作是为了达到 B 目的。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、造句法"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“为了 B 而去 A”。例如：“健身 : 减肥” -> “为了减肥而去健身”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、易错点"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "千万不要把目的对应和因果对应搞混。因果是自然发生的（下雨导致地湿），目的是主观意愿（打伞为了防雨）。"}]}]}$$ AS jsonb), NULL, '目的对应的核心考点与解题技巧。', category_node.id, CAST('["判断推理", "目的对应"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_judgement_analogy_corresponding_purpose", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
